def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    yesterday_bids = []
    urgent_opp_bids = []
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            prev_bid = 0.0
            if prev and prev.get('bid') is not None:
                prev_bid = float(prev.get('bid', 0.0))
                yesterday_bids.append(prev_bid)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_bids.append(prev_bid)
            if opp.get('budget', 0) >= 200 and prev_bid >= 100:
                rich_aggressive += 1

    slots = max(1, int(supply // WATER_REQ))
    pressure = len(alive_opps) - slots

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if slots == 1:
        danger += 2
    if pressure >= 2:
        danger += 1
    if rich_aggressive >= 2:
        danger += 1

    safe_floor = DAILY_SALARY * 0.22
    conserve_bid = DAILY_SALARY * 0.32
    contest_bid = DAILY_SALARY * 0.78
    emergency_bid = DAILY_SALARY * 1.08

    if not alive_opps:
        bid = safe_floor
    elif danger <= 1:
        if highest_prev >= 120:
            bid = safe_floor
        else:
            bid = max(conserve_bid, min(55.0, highest_prev + 2.0))
    elif danger <= 3:
        if urgent_prev >= 120:
            bid = contest_bid
        else:
            bid = max(contest_bid, urgent_prev + 3.0)
    else:
        if hp <= 2 or no_water_days >= 2:
            bid = max(emergency_bid, urgent_prev + 6.0)
        else:
            bid = max(contest_bid + 10.0, urgent_prev + 4.0)

    if day >= 8:
        bid += 8.0
    if day >= 9:
        bid += 10.0

    if budget < DAILY_SALARY:
        bid = min(bid, budget)
    else:
        reserve_days = max(0, 10 - int(day))
        reserve_target = reserve_days * DAILY_SALARY * 0.18
        spend_cap = max(0.0, budget - reserve_target)
        bid = min(bid, max(DAILY_SALARY * 0.2, spend_cap))

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents alive, take what we can.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace.
    prev_bids = []
    prev_by_id = {}
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            prev_bids.append(b_val)
            prev_by_id[opp_id] = b_val

    # Baseline pressure estimate.
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
        # If Cindy-like behavior exists (very high bids), treat as strong competition.
        strong_competition = highest_prev >= 0.95 * 300.0 or highest_prev >= 0.9 * 195.0
    else:
        highest_prev = 0.0
        second_prev = 0.0
        strong_competition = False

    # Supply regime: higher supply means we can bid less and still likely secure water.
    # Convert supply to an integer bucket safely.
    # If supply is near max (25), competition can be relaxed; if near min (15), we must be more aggressive.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Urgency based on hp and starvation days.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    if hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.7
    if no_water_days >= 4:
        urgency += 1.0

    # Decide target bid.
    # Strategy: if Cindy/others bid max yesterday, we slightly underbid/overbid depending on our urgency.
    # We do not know today's hidden bids, so we aim to be competitive but not waste budget.
    # Target around: (second_prev + small increment) when strong competition, else around (highest_prev * 0.75).
    if strong_competition:
        # If we are healthy, try to free budget: bid near second_prev.
        # If we are urgent, bid closer to highest_prev.
        if urgency >= 1.0:
            target = max(highest_prev * 0.92, second_prev + 5.0)
        else:
            target = min(highest_prev - 5.0, max(second_prev + 2.0, highest_prev * 0.78))
    else:
        # Moderate competition: bid to beat typical bids.
        base = highest_prev * (0.70 if urgency < 0.8 else 0.85)
        # Also account for supply: bid less when supply is high.
        supply_adjust = 1.0 - 0.25 * supply_ratio  # 1.0 at min supply, 0.75 at max supply
        target = base * supply_adjust + (5.0 if urgency >= 1.0 else 0.0)

    # Ensure we bid at least enough to matter but never exceed budget.
    # Use a floor tied to urgency.
    min_bid = 0.0
    if urgency >= 1.0:
        min_bid = DAILY_SALARY * 0.75
    elif urgency >= 0.6:
        min_bid = DAILY_SALARY * 0.55
    else:
        min_bid = DAILY_SALARY * 0.35

    # Cap target by budget and a reasonable fraction of DAILY_SALARY to avoid bankrupting.
    # (We do not know total rounds, but preserving budget is key.)
    cap = budget
    if cap <= 0.0:
        return 0.0

    # Slightly more aggressive late in episode (day index heuristic).
    # episode_days is 10; day_context day likely 0..9 or 1..10. We'll treat higher day as later.
    try:
        later = float(day) / 10.0
    except Exception:
        later = 0.5
    if later < 0.0:
        later = 0.0
    if later > 1.0:
        later = 1.0

    # Allow higher cap near the end.
    cap = min(cap, DAILY_SALARY * (0.95 if later >= 0.7 else 0.65))

    final_bid = float(target)
    if final_bid < min_bid:
        final_bid = min_bid
    if final_bid > cap:
        final_bid = cap

    # Never negative.
    if final_bid < 0.0:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    if day_context['supply'] < 18:
        bid = min(my_status['budget'], avg_prev * 1.15)
    else:
        bid = min(my_status['budget'], avg_prev * 0.9)
    if my_status['hp'] < 4:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    return float(max(1.0, bid))
